head.script:
scwin.onpageload = function () {
    dlt_a.setJSON([
        { "name" : "홍길동", "cal" : "", "txt" : "" },
        { "name" : "김철수", "cal" : "", "txt" : "" }
    ]);
};

// 결과 출력용 구분 ([A] cal / [B] txt)
scwin.getTag = function (colIndex) {
    let colId = grd_a.getColumnID(colIndex);
    if (colId === "cal") {
        return "[A] ";
    }
    if (colId === "txt") {
        return "[B] ";
    }
    return "";
};

// 편집 진입 직후 입력창 값 / 커서 위치 출력
scwin.grd_a_onbeforeedit = function (rowIndex, colIndex, value) {
    let tag = scwin.getTag(colIndex);
    if (tag === "") {
        return;
    }
    let colId = grd_a.getColumnID(colIndex);
    setTimeout(function () {
        let el = document.activeElement;
        scwin.setReturnValue(tag + dlt_a.getCellData(rowIndex, "name") + " 행 " + colId + " Cell 편집 진입 : 입력창 '" + el.value + "' / 커서 위치 " + el.selectionStart);
    }, 100);
};

// 편집 종료 후 Cell 표시값 / DataList 값 출력
scwin.grd_a_onafteredit = function (rowIndex, colIndex, value) {
    let tag = scwin.getTag(colIndex);
    if (tag === "") {
        return;
    }
    let colId = grd_a.getColumnID(colIndex);
    let td = document.getElementById(grd_a.id + "_cell_" + rowIndex + "_" + colIndex);
    scwin.setReturnValue(tag + dlt_a.getCellData(rowIndex, "name") + " 행 " + colId + " Cell 편집 종료 : Cell 표시값 '" + (td ? td.textContent.trim() : "") + "' / DataList 값 '" + dlt_a.getCellData(rowIndex, colId) + "'");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
